import { makeMesh, clamp } from '../../character-prototype/preview/rig.mjs';
import { contactWeights } from '../../character-prototype/preview/contact-rig.mjs';
import { regionUniforms } from '../src/gl-scene.mjs';
import { viewArcPoint, CONTINUOUS_RANGE, VIEW_ARC_GAPS } from '../src/view-arc.mjs';
import { projectFromPrototypeMesh } from '../src/project.mjs';

main().catch(e => { const el = document.querySelector("#state"); if (el) el.textContent = "启动错误: " + String(e && e.message || e).slice(0, 160); console.error(e); });
function main() { return (async () => {
  const config = {"format": "qingyang-mesh-2.5d-v1", "description": "Editable manually traced geometry and deformation weights. This is not a Cubism model or reconstructed 3D volume.", "canvas": [1086, 1448], "texture": "original.png", "background": "background.png", "normalizedViewRange": [-1, 1], "characterOutline": [[251, 0], [641, 0], [666, 16], [702, 4], [737, 20], [758, 53], [755, 93], [738, 127], [713, 155], [699, 190], [695, 229], [704, 271], [722, 310], [750, 340], [793, 368], [826, 389], [863, 423], [890, 468], [909, 519], [925, 577], [937, 646], [945, 718], [961, 800], [972, 868], [988, 921], [1005, 973], [1013, 1011], [1024, 1047], [1022, 1070], [1021, 1127], [1024, 1205], [1023, 1316], [1029, 1380], [1026, 1448], [87, 1448], [115, 1405], [152, 1352], [211, 1301], [267, 1277], [328, 1256], [356, 1229], [303, 1233], [266, 1252], [223, 1262], [190, 1246], [173, 1228], [166, 1208], [164, 1189], [182, 1164], [207, 1148], [231, 1130], [197, 1130], [122, 1120], [56, 1113], [0, 1105], [0, 832], [48, 859], [94, 879], [124, 878], [157, 875], [191, 879], [224, 884], [258, 883], [305, 879], [352, 878], [398, 873], [446, 865], [481, 855], [465, 826], [462, 793], [468, 759], [477, 727], [493, 688], [516, 635], [536, 584], [549, 534], [548, 496], [557, 466], [568, 446], [587, 429], [603, 414], [578, 397], [554, 381], [534, 376], [523, 394], [512, 411], [495, 428], [478, 429], [457, 418], [441, 403], [417, 395], [403, 385], [387, 381], [375, 374], [362, 366], [343, 360], [327, 348], [318, 335], [312, 324], [300, 320], [277, 334], [264, 354], [256, 384], [250, 415], [249, 454], [240, 479], [227, 459], [213, 428], [201, 386], [188, 349], [184, 309], [188, 274], [183, 238], [185, 201], [192, 161], [203, 125], [220, 88], [235, 48]], "holes": [[[386, 981], [444, 972], [507, 967], [552, 976], [602, 993], [645, 1013], [586, 1038], [526, 1056], [463, 1072], [405, 1088]]], "foregroundOutline": [[1026, 801], [1086, 792], [1086, 1448], [958, 1448], [957, 1414], [1028, 1380]], "pins": [{"name": "paper and hands", "region": [0, 850, 392, 1268]}, {"name": "seated support", "region": [0, 1310, 1086, 1448]}], "springs": {"body": {"frequency": 2.4, "damping": 0.88, "limit": 1.2}, "chest": {"frequency": 3.2, "damping": 0.5, "limit": 1.4}, "hair": {"frequency": 1.7, "damping": 0.58, "limit": 1.5}}, "limits": {"bodyPixels": 5.0, "chestPixels": 7.0, "hairPixels": 10.0, "triangleEdgePixels": 27}};
  const project = projectFromPrototypeMesh(config);
  const layer = project.layers.find(l => l.kind === 'character');
  const [W, H] = project.canvas;

  // 2D canvas 简版渲染：用 JS 版公式对网格逐顶点形变（与 gl-scene VERT 同公式），绘制到画布。
  const img = new Image(); await new Promise((res, rej) => { img.onload = res; img.onerror = () => rej(new Error('原图加载失败')); img.src = 'data:image/jpeg;base64,'; setTimeout(() => rej(new Error('原图加载超时')), 6000); });
  const positions = makeMesh([[0, 0], [W, 0], [W, H], [0, H]], [], 27);
  const pins = contactWeights(positions);
  const scale = 820 / W;

  function deform(viewX) {
    const out = positions.slice();
    const ru = regionUniforms(layer);
    const bell = (px, py, b) => { const dx = (px - b[0]) / b[2], dy = (py - b[1]) / b[3]; return Math.exp(-(dx * dx + dy * dy) * 2); };
    const ssy = (y) => 1 - (() => { const t = Math.max(0, Math.min(1, (y - ru.head[0]) / (ru.head[1] - ru.head[0]))); return t * t * (3 - 2 * t); })();
    for (let i = 0; i < positions.length; i += 2) {
      const px = positions[i], py = positions[i + 1];
      const head = ssy(py);
      const neck = bell(px, py, ru.bell0), chest = bell(px, py, ru.bell1), shoulder = bell(px, py, ru.bell2);
      const torso = bell(px, py, ru.bell3), cheek = bell(px, py, ru.bell4);
      const depth = ru.depth[4] * torso + ru.depth[3] * shoulder + ru.depth[2] * chest + head * (ru.depth[0] + ru.head[3] * cheek);
      let tx = viewX * depth + (px - ru.squeeze[2]) * (ru.squeeze[0] * viewX) * head;
      let ty = (px - ru.squeeze[3]) * (ru.squeeze[1] * viewX) * torso;
      // 逐顶点（JS 版无弹簧，模拟固定位移上限）
      const active = 1 - pins[i / 2];
      out[i] = px + tx * active; out[i + 1] = py + ty * active;
    }
    return out;
  }

  const cv = document.querySelector('#stage'), ctx = cv.getContext('2d');
  function draw(viewX) {
    const d = deform(viewX);
    ctx.fillStyle = '#222'; ctx.fillRect(0, 0, cv.width, cv.height);
    ctx.save(); ctx.scale(scale, scale);
    // 连续范围标注带
    ctx.fillStyle = 'rgba(124, 252, 0, 0.06)';
    ctx.fillRect(W / 2 + viewX * 0 - 200, 0, 400, H);
    // 逐三角形贴图（简化：按中心点仿射近似不精确，改用整体位移场绘制——以每三角形 3 顶点位移做仿射贴图）
    for (let t = 0; t < positions.length; t += 6) {
      const sx = [positions[t], positions[t + 2], positions[t + 4]], sy = [positions[t + 1], positions[t + 3], positions[t + 5]];
      const dx = [d[t], d[t + 2], d[t + 4]], dy = [d[t + 1], d[t + 3], d[t + 5]];
      // 源三角形 → 目标三角形 仿射
      const cxs = (sx[0] + sx[1] + sx[2]) / 3, cys = (sy[0] + sy[1] + sy[2]) / 3;
      const cxd = (dx[0] + dx[1] + dx[2]) / 3, cyd = (dy[0] + dy[1] + dy[2]) / 3;
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(dx[0], dy[0]); ctx.lineTo(dx[1], dy[1]); ctx.lineTo(dx[2], dy[2]); ctx.closePath();
      ctx.clip();
      // 仿射：源→目标（用质心平移 + 线性近似）
      const a11 = 1, a22 = 1, tx = cxd - cxs, ty = cyd - cys;
      ctx.transform(a11, 0, 0, a22, tx, ty);
      ctx.drawImage(img, 0, 0);
      ctx.restore();
    }
    ctx.restore();
    document.querySelector('#state').textContent =
      Math.abs(viewX) <= CONTINUOUS_RANGE
        ? `✓ 视角 ${viewX.toFixed(2)} 在连续范围 ±${CONTINUOUS_RANGE} 内：局部轮廓/遮挡连续，接触点固定`
        : `⚠ 视角 ${viewX.toFixed(2)} 超出连续范围 ±${CONTINUOUS_RANGE}：同一曲面滑移放大，无新轮廓生成（不冒充侧背）`;
  }

  const slider = document.querySelector('#slider');
  slider.addEventListener('input', () => {
    const v = Number(slider.value) / 100;
    document.querySelector('#val').textContent = v.toFixed(2);
    document.querySelector('#deg').textContent = (v * 28).toFixed(0) + '°';
    draw(v);
  });
  draw(0);

  // 视角弧响应表
  const rows = ['', '-0.50', '-0.35', '0', '+0.35', '+0.50'];
  const ids = ['face', 'shoulder', 'torso', 'hairRoot'];
  const table = document.querySelector('#arctable');
  const head = document.createElement('tr');
  head.innerHTML = '<th>锚点 \\ 视角</th>' + rows.slice(1).map(v => `<th>${v}</th>`).join('');
  table.append(head);
  for (const id of ids) {
    const tr = document.createElement('tr');
    tr.innerHTML = `<td>${id}</td>` + rows.slice(1).map(v => {
      const pt = viewArcPoint(Number(v), layer).find(p => p.id === id);
      return `<td>${pt.turnX > 0 ? '+' : ''}${pt.turnX}px</td>`;
    }).join('');
    table.append(tr);
  }
  // 缺口清单
  for (const g of VIEW_ARC_GAPS) {
    const li = document.createElement('li');
    li.innerHTML = `<b class="warn">${g.gap}</b>：<span class="dim">${g.detail}</span>`;
    document.querySelector('#gaps').append(li);
  }
})(); }
